"""One-time script to seed Garmin OAuth tokens into the Railway DB.

Run locally first to capture tokens, then run on Railway:
  railway run python scripts/seed_garmin_tokens.py

The TOKENS dict below must be populated before running on Railway.
Run this locally first to print the values:
  python scripts/seed_garmin_tokens.py --export
"""

import sys

def export_tokens():
    from running_coach_ai.database.session import get_session
    from running_coach_ai.database.models import Athlete

    with get_session() as db:
        rows = db.query(Athlete.id, Athlete.garmin_oauth_tokens).filter(
            Athlete.garmin_oauth_tokens.isnot(None)
        ).all()

    if not rows:
        print("No athletes with tokens in local DB.")
        return

    print("# Paste the TOKENS dict below into this script, then run on Railway")
    print("TOKENS = {")
    for athlete_id, token in rows:
        print(f"    {athlete_id}: {token!r},")
    print("}")


def seed_tokens():
    from running_coach_ai.database.session import get_session
    from running_coach_ai.database.models import Athlete

    if not TOKENS:
        print("TOKENS dict is empty — populate it first (run with --export locally).")
        sys.exit(1)

    with get_session() as db:
        updated = 0
        for athlete_id, token in TOKENS.items():
            a = db.get(Athlete, athlete_id)
            if not a:
                print(f"Athlete {athlete_id} not found in DB — skipping")
                continue
            a.garmin_oauth_tokens = token
            updated += 1
            print(f"Seeded tokens for athlete {athlete_id} ({a.garmin_email})")

    print(f"Done — {updated} athlete(s) updated.")


